}
.dark .focus-ring-offset:focus-visible {
  outline-color: oklch(0.6 0.2 250);
}

/* Card gradient border — animated rotating gradient border */
.card-gradient-border {
  position: relative;
  overflow: hidden;
  border: none;
}
.card-gradient-border::before {
  content: '';
  position: absolute;
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  background: conic-gradient(from var(--gradient-angle, 0deg), oklch(0.55 0.2 250), oklch(0.65 0.2 160), oklch(0.7 0.18 80), oklch(0.55 0.2 250));
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: gradient-rotate 4s linear infinite;
  opacity: 0.6;
  transition: opacity 0.3s ease;
}
.card-gradient-border:hover::before {
  opacity: 1;
}
@property --gradient-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}
@keyframes gradient-rotate {
  to { --gradient-angle: 360deg; }
}

/* Data badge — small metric badge with background pill */
.data-badge {
