}

/* Tab active indicator — animated bottom indicator for active tab */
.tab-active-indicator {
  position: relative;
}
.tab-active-indicator::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 50%;
  transform: translateX(-50%);
  width: 60%;
  height: 2px;
  background: linear-gradient(90deg, oklch(0.55 0.2 250), oklch(0.65 0.18 160));
  border-radius: 1px;
  transition: width 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.tab-active-indicator:hover::after,
.tab-active-indicator[data-state="active"]::after {
  width: 80%;
}

/* Status indicator dot — small animated status dot */
.status-dot-animated {
  position: relative;
  width: 8px;
  height: 8px;
  border-radius: 50%;
}
.status-dot-animated::after {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  opacity: 0;
  animation: status-dot-ring 2s ease-out infinite;
}
@keyframes status-dot-ring {
  0% { transform: scale(0.8); opacity: 0.8; }
  100% { transform: scale(2); opacity: 0; }
}

/* Scrollbar hidden utility */
.scrollbar-hidden::-webkit-scrollbar {
