}

/* Animated gradient border (for premium drawer headers) */
@keyframes gradient-border-shift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}
.gradient-border-animated-v2 {
  position: relative;
  background-clip: padding-box;
}
.gradient-border-animated-v2::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, hsl(var(--primary) / 0.4), transparent 40%, hsl(var(--primary) / 0.2));
