  to { opacity: 1; transform: translateY(0); }
}

/* Improvement badge */
.wps-improved-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 0.6875rem;
  font-weight: 600;
  background: rgba(16, 185, 129, 0.1);
