}

/* Metric Bars */
.wps-metric-bar {
  transition: width 0.8s ease-out;
}
.wps-metric-green { background: linear-gradient(90deg, #22c55e, #4ade80); }
.wps-metric-amber { background: linear-gradient(90deg, #eab308, #facc15); }
.wps-metric-red { background: linear-gradient(90deg, #ef4444, #f87171); }

/* Strength & Improvement Cards */
.wps-strength-card {
  border-left: 3px solid #22c55e;
}
.wps-improve-card {
