}

/* Metrics Table */
.wps-metrics-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.wps-metrics-table th {
  padding: 10px 14px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #6b7280;
  border-bottom: 2px solid #e5e7eb;
