}

.wps-rank-cell {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.wps-rank-gold { background: linear-gradient(135deg, #fbbf24, #f59e0b); color: white; }
.wps-rank-silver { background: linear-gradient(135deg, #d1d5db, #9ca3af); color: white; }
.wps-rank-bronze { background: linear-gradient(135deg, #d97706, #b45309); color: white; }

/* Champion Cards */
.wps-champion-card {
  border: 1px solid #e9d5ff;
  border-radius: 12px;
  background: white;
  transition: all 0.25s;
  cursor: default;
}
.wps-champion-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 24px rgba(124, 58, 237, 0.15);
  border-color: #c4b5fd;
}
.wps-champion-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto;
  background: linear-gradient(135deg, #ede9fe, #ddd6fe);
