}
.wps-alert-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-radius: 8px;
  border-left: 3px solid;
  transition: transform 0.15s, box-shadow 0.15s;
}
.wps-alert-item:hover {
