}
.dark .wps-chart-card {
  background: #1e1b2e;
  border-color: #374151;
}
.dark .wps-tab.active {
  color: #c4b5fd;
  background: #1e1b2e;
  box-shadow: 0 -2px 8px rgba(124, 58, 237, 0.15);
}
.dark .wps-tab.active::after {
  background: linear-gradient(90deg, #7c3aed, #d946ef);
}
.dark .wps-change-card {
  background: #1e1b2e;
  border-color: #374151;
}
.dark .wps-kpi-cat-btn {
  background: #1e1b2e;
  border-color: #374151;
  color: #9ca3af;
}
.dark .wps-kpi-cat-btn.active {
  color: white;
}
.dark .wps-bic-card {
  background: linear-gradient(135deg, #1e1b2e, #2d1b69);
  border-color: #4c1d95;
}
.dark .wps-metrics-table th {
  background: #1e1b2e;
  color: #9ca3af;
  border-bottom-color: #374151;
}
.dark .wps-metrics-table td {
  border-bottom-color: #374151;
}
.dark .wps-metrics-row:hover {
  background: rgba(124, 58, 237, 0.08);
}
.dark .wps-wh-mini-kpi {
  background: rgba(255,255,255,0.05);
}
.dark .wps-ranking-top {
  background: linear-gradient(90deg, rgba(251, 191, 36, 0.1), transparent);
}
.dark .wps-champion-card {
  background: #1e1b2e;
  border-color: #4c1d95;
}
.dark .wps-champion-icon {
  background: linear-gradient(135deg, #4c1d95, #6d28d9);
  color: #c4b5fd;
}
.dark .wps-alerts-card {
  background: #1e1b2e;
  border-color: #422006;
}
.dark .wps-alert-warning {
  background: rgba(245, 158, 11, 0.08);
}
.dark .wps-strength-card {
  border-left-color: #22c55e;
  background: rgba(34, 197, 94, 0.03);
}
.dark .wps-improve-card {
