.twm-filter-select:hover { border-color: #6366f1; }
.twm-filter-select option { color: #1f2937; background: white; }

/* Match Table */
.twm-match-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.twm-match-table th {
  padding: 10px 14px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #6b7280;
  border-bottom: 2px solid #e5e7eb;
  background: #fafafa;
}
.twm-match-table td {
  padding: 10px 14px;
  border-bottom: 1px solid #f3f4f6;
}
.twm-match-row {
  cursor: pointer;
  transition: background 0.15s;
}
.twm-match-row:hover {
  background: #eef2ff;
}
.twm-row-alert {
  background: #fef2f2;
}
.twm-row-alert:hover {
  background: #fee2e2;
}

/* Score Cell */
.twm-score-cell {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 24px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
  font-family: monospace;
