  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
}

.cc-tab:hover {
  color: hsl(var(--foreground));
  background: hsl(var(--card));
}

.cc-tab-active {
  color: white;
  background: linear-gradient(135deg, #06b6d4, #3b82f6);
  box-shadow: 0 2px 8px rgba(6, 182, 212, 0.3);
}

