.dark .haz-kpi-amber { background: linear-gradient(135deg, rgba(245, 158, 11, 0.15), rgba(245, 158, 11, 0.08)); }
.dark .haz-kpi-purple { background: linear-gradient(135deg, rgba(139, 92, 246, 0.15), rgba(139, 92, 246, 0.08)); }
.dark .haz-kpi-blue { background: linear-gradient(135deg, rgba(59, 130, 246, 0.15), rgba(59, 130, 246, 0.08)); }

.haz-kpi-icon { color: hsl(var(--muted-foreground)); }
.haz-kpi-value { font-size: 1.5rem; font-weight: 700; color: hsl(var(--foreground)); line-height: 1.2; }
.haz-kpi-label { font-size: 0.7rem; color: hsl(var(--muted-foreground)); margin-top: 2px; }

/* Cards */
