.haz-drawer { position: fixed; top: 0; right: 0; width: 440px; max-width: 90vw; height: 100%; background: hsl(var(--card)); border-left: 1px solid hsl(var(--border)); box-shadow: -8px 0 30px rgba(0, 0, 0, 0.15); overflow-y: auto; animation: haz-slide-in 0.3s ease; z-index: 51; }
@keyframes haz-slide-in { from { transform: translateX(100%); } to { transform: translateX(0); } }
.haz-drawer-header { display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; border-bottom: 1px solid hsl(var(--border)); }
.haz-drawer-title { font-size: 0.9rem; font-weight: 600; }
.haz-drawer-body { padding: 20px; }
.haz-drawer-section { margin-bottom: 20px; }
.haz-drawer-section-title { font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: hsl(var(--muted-foreground)); margin-bottom: 10px; padding-bottom: 4px; border-bottom: 1px solid hsl(var(--border)); }
.haz-drawer-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.haz-drawer-label { display: block; font-size: 0.65rem; color: hsl(var(--muted-foreground)); margin-bottom: 2px; }
.haz-drawer-value { font-size: 0.8rem; font-weight: 500; color: hsl(var(--foreground)); }

/* Stagger */
@keyframes haz-slide-up { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
.haz-stagger-0 { animation: haz-slide-up 0.4s ease both; animation-delay: 0ms; }
.haz-stagger-1 { animation: haz-slide-up 0.4s ease both; animation-delay: 50ms; }
.haz-stagger-2 { animation: haz-slide-up 0.4s ease both; animation-delay: 100ms; }
.haz-stagger-3 { animation: haz-slide-up 0.4s ease both; animation-delay: 150ms; }
.haz-stagger-4 { animation: haz-slide-up 0.4s ease both; animation-delay: 200ms; }
.haz-stagger-5 { animation: haz-slide-up 0.4s ease both; animation-delay: 250ms; }
.haz-stagger-6 { animation: haz-slide-up 0.4s ease both; animation-delay: 300ms; }
.haz-stagger-7 { animation: haz-slide-up 0.4s ease both; animation-delay: 350ms; }
.haz-stagger-8 { animation: haz-slide-up 0.4s ease both; animation-delay: 400ms; }
.haz-stagger-9 { animation: haz-slide-up 0.4s ease both; animation-delay: 450ms; }
.haz-stagger-10 { animation: haz-slide-up 0.4s ease both; animation-delay: 500ms; }
.haz-stagger-11 { animation: haz-slide-up 0.4s ease both; animation-delay: 550ms; }

/* Responsive */
@media (max-width: 1024px) { .haz-header-title { font-size: 1rem; } .haz-kpi-value { font-size: 1.2rem; } }
@media (max-width: 768px) {
