.sn-drawer-info-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.6rem;
}
.sn-drawer-info-item {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  padding: 0.5rem 0.6rem;
  border-radius: 8px;
  background: #1e293b;
  border: 1px solid #334155;
}
.sn-info-label {
  font-size: 0.68rem;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 500;
}
.sn-info-value {
  font-size: 0.8rem;
  color: #e2e8f0;
  font-weight: 500;
}
.sn-info-mono {
  font-family: "JetBrains Mono", "Fira Code", monospace;
  color: #5eead4;
  font-size: 0.76rem;
}
.sn-info-temp {
