}
.sn-quarantine-text {
  color: #fca5a5;
  font-size: 0.82rem;
  margin: 0;
}

/* Timeline */
.sn-timeline {
  display: flex;
  flex-direction: column;
}
.sn-timeline-item {
  display: flex;
  gap: 0.75rem;
  position: relative;
}
.sn-timeline-connector {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
}
.sn-timeline-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
  z-index: 1;
  box-shadow: 0 0 6px rgba(0, 0, 0, 0.3);
}
.sn-timeline-line {
  width: 2px;
  flex: 1;
  min-height: 20px;
  background: #334155;
}
.sn-timeline-content {
  flex: 1;
  padding-bottom: 1rem;
}
.sn-timeline-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.3rem;
}
.sn-timeline-event {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: capitalize;
}
.sn-timeline-time {
  font-size: 0.7rem;
  color: #64748b;
  white-space: nowrap;
}
.sn-timeline-details {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 0.25rem;
}
.sn-timeline-detail {
