}
.pkg-drawer-panel {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 520px;
  background: white;
  z-index: 51;
  box-shadow: -8px 0 30px rgba(0, 0, 0, 0.12);
