@keyframes pkgFadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes pkgSlideIn { from { transform: translateX(100%); } to { transform: translateX(0); } }

/* --- Drawer Status Banner --- */
.pkg-drawer-status-banner {
  padding: 16px 20px;
  border-radius: 10px;
  margin-bottom: 16px;
}
.pkg-drawer-banner-active { background: linear-gradient(135deg, #dcfce7, #bbf7d0); border: 1px solid #86efac; }
