/* ============================================================
   R127: Slotting Optimization & Bin Assignment Management
   Theme: Purple + Orange + Teal (#8b5cf6, #f97316, #14b8a6)
   Prefix: slot-*
   ============================================================ */

/* --- Animated Gradient Top Border (Purple → Orange → Teal, 6s) --- */
.slot-header-banner {
  position: relative;
  background: linear-gradient(135deg, #f5f3ff 0%, #fff7ed 50%, #f0fdfa 100%);
  border-radius: 16px;
  padding: 24px 28px 20px;
  overflow: hidden;
  border: 1px solid rgba(139, 92, 246, 0.1);
}
.slot-header-banner::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, #8b5cf6, #f97316, #14b8a6, #8b5cf6);
  background-size: 300% 100%;
  animation: slotGradientShift 6s ease infinite;
}
@keyframes slotGradientShift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* --- Dark Mode Header --- */
:is(.dark .slot-header-banner) {
  background: linear-gradient(135deg, rgba(139,92,246,0.08) 0%, rgba(249,115,22,0.08) 50%, rgba(20,184,166,0.08) 100%);
  border-color: rgba(139, 92, 246, 0.15);
}

/* --- KPI Cards --- */
.slot-kpi-card {
  border-radius: 14px;
  padding: 20px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  position: relative;
  overflow: hidden;
}
.slot-kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px -5px rgba(0, 0, 0, 0.1);
}
.slot-kpi-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
}
.slot-kpi-purple { background: linear-gradient(135deg, #f5f3ff 0%, #ede9fe 100%); }
.slot-kpi-purple::after { background: linear-gradient(90deg, #8b5cf6, #a78bfa); }
.slot-kpi-orange { background: linear-gradient(135deg, #fff7ed 0%, #ffedd5 100%); }
.slot-kpi-orange::after { background: linear-gradient(90deg, #f97316, #fb923c); }
.slot-kpi-teal { background: linear-gradient(135deg, #f0fdfa 0%, #ccfbf1 100%); }
