.slot-kpi-rose { background: linear-gradient(135deg, #fff1f2 0%, #ffe4e6 100%); }
.slot-kpi-rose::after { background: linear-gradient(90deg, #f43f5e, #fb7185); }
.slot-kpi-sky { background: linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%); }
