  padding: 1.25rem 1.5rem;
}

.dark .wave-header {
  background: linear-gradient(135deg, rgba(245,158,11,0.08) 0%, rgba(99,102,241,0.08) 50%, rgba(16,185,129,0.08) 100%);
}

@keyframes wave-header-shift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

.wave-header-icon {
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 0.75rem;
  background: linear-gradient(135deg, #f59e0b, #6366f1);
