/* Timeline */
.rp-timeline { display: flex; flex-direction: column; gap: 0.75rem; }
.rp-timeline-track { display: flex; align-items: flex-start; justify-content: space-between; position: relative; padding: 8px 0; }
.rp-timeline-step { display: flex; flex-direction: column; align-items: center; gap: 4px; position: relative; z-index: 1; }
.rp-timeline-dot { width: 14px; height: 14px; border-radius: 50%; background: #e2e8f0; border: 2px solid #cbd5e1; transition: all 0.3s; }
.rp-dot-done { background: #ec4899; border-color: #db2777; box-shadow: 0 0 6px rgba(236, 72, 153, 0.4); }
.rp-dot-current { background: #06b6d4; border-color: #0891b2; box-shadow: 0 0 8px rgba(6, 182, 212, 0.5); animation: rp-pulse-dot 1.5s infinite; }
@keyframes rp-pulse-dot { 0%, 100% { box-shadow: 0 0 4px rgba(6, 182, 212, 0.4); } 50% { box-shadow: 0 0 12px rgba(6, 182, 212, 0.7); } }
.rp-timeline-label { font-size: 0.65rem; color: #94a3b8; }
.rp-timeline-date { font-size: 0.6rem; color: #cbd5e1; }
.rp-label-done { color: #db2777; font-weight: 500; }
.rp-label-current { color: #0891b2; font-weight: 600; }
.rp-timeline-connector { flex: 1; height: 2px; background: #e2e8f0; position: absolute; top: 14px; left: 50%; right: -50%; z-index: 0; }
