/* Feedback Box */
.rp-feedback-box { padding: 0.75rem; background: rgba(16, 185, 129, 0.05); border: 1px solid rgba(16, 185, 129, 0.15); border-radius: 8px; }
:is(.dark .rp-feedback-box) { background: rgba(16, 185, 129, 0.08); border-color: rgba(16, 185, 129, 0.2); }

/* Drawer Footer */
.rp-drawer-footer { display: flex; flex-wrap: wrap; gap: 8px; padding-top: 0.75rem; border-top: 1px solid #e2e8f0; margin-top: 0.25rem; }
.rp-footer-item { flex: 1; min-width: 80px; display: flex; flex-direction: column; gap: 2px; }
:is(.dark .rp-drawer-footer) { border-top-color: #334155; }

/* Staggered Animations */
.rp-container > .rp-header { animation: rp-stagger-1 0.4s ease-out both; }
.rp-container > .rp-tabs { animation: rp-stagger-2 0.4s ease-out 0.1s both; }
@keyframes rp-stagger-1 { from { opacity: 0; transform: translateY(-12px); } to { opacity: 1; transform: translateY(0); } }
@keyframes rp-stagger-2 { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* Responsive */
@media (max-width: 768px) {
  .rp-header-content { flex-direction: column; align-items: flex-start; }
  .rp-header-badges { width: 100%; }
  .rp-info-grid { grid-template-columns: 1fr; }
  .rp-location-viz { flex-wrap: wrap; justify-content: center; }
  .rp-location-line { margin: 4px 8px; }
  .rp-drawer-panel { width: 100%; max-width: 100%; }
}
/* ============================================================================
   R133: Putaway Management & Bin Optimization — pa-* CSS
   Theme: Indigo (#6366f1) + Emerald (#10b981) + Amber (#f59e0b)
   ============================================================================ */

/* ── Animated Gradient Top Border ─────────────────────────────────────────── */
.pa-container {
  position: relative;
  animation: pa-fade-in 0.4s ease-out;
}
.pa-container::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, #6366f1, #10b981, #f59e0b, #6366f1);
  background-size: 300% 100%;
  animation: pa-gradient-border 6s linear infinite;
  border-radius: 999px 999px 0 0;
  z-index: 10;
}
@keyframes pa-gradient-border {
  0% { background-position: 0% 50%; }
  100% { background-position: 300% 50%; }
}
@keyframes pa-fade-in {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── KPI Cards ──────────────────────────────────────────────────────────── */
.pa-kpi-card {
  position: relative;
  overflow: hidden;
  border-radius: 12px;
  padding: 1rem 1.25rem;
  transition: transform 0.2s, box-shadow 0.2s;
}
.pa-kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
}
.pa-kpi-card::after {
  content: '';
  position: absolute;
  top: -20px; right: -20px;
  width: 80px; height: 80px;
  border-radius: 50%;
  opacity: 0.15;
}
.pa-kpi-indigo { background: linear-gradient(135deg, #6366f1, #818cf8); color: #fff; }
.pa-kpi-indigo::after { background: #fff; }
.pa-kpi-emerald { background: linear-gradient(135deg, #10b981, #34d399); color: #fff; }
.pa-kpi-emerald::after { background: #fff; }
.pa-kpi-amber { background: linear-gradient(135deg, #f59e0b, #fbbf24); color: #fff; }
.pa-kpi-amber::after { background: #fff; }
.pa-kpi-violet { background: linear-gradient(135deg, #8b5cf6, #a78bfa); color: #fff; }
.pa-kpi-violet::after { background: #fff; }
.pa-kpi-pink { background: linear-gradient(135deg, #ec4899, #f472b6); color: #fff; }
.pa-kpi-pink::after { background: #fff; }
.pa-kpi-cyan { background: linear-gradient(135deg, #06b6d4, #22d3ee); color: #fff; }
.pa-kpi-cyan::after { background: #fff; }

/* Dark mode KPIs */
:is(.dark .pa-kpi-indigo) { background: linear-gradient(135deg, #4338ca, #6366f1); }
:is(.dark .pa-kpi-emerald) { background: linear-gradient(135deg, #047857, #10b981); }
:is(.dark .pa-kpi-amber) { background: linear-gradient(135deg, #b45309, #f59e0b); }
:is(.dark .pa-kpi-violet) { background: linear-gradient(135deg, #6d28d9, #8b5cf6); }
:is(.dark .pa-kpi-pink) { background: linear-gradient(135deg, #be185d, #ec4899); }
:is(.dark .pa-kpi-cyan) { background: linear-gradient(135deg, #0e7490, #06b6d4); }

/* ── Status Badges ───────────────────────────────────────────────────────── */
.pa-status-pending {
  background: rgba(148, 163, 184, 0.15);
  color: #64748b;
  border: 1px solid rgba(148, 163, 184, 0.3);
  padding: 2px 10px;
  border-radius: 9999px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.pa-status-assigned {
  background: rgba(245, 158, 11, 0.15);
  color: #d97706;
  border: 1px solid rgba(245, 158, 11, 0.3);
  padding: 2px 10px;
  border-radius: 9999px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.pa-status-in-progress {
  background: rgba(99, 102, 241, 0.15);
  color: #4f46e5;
  border: 1px solid rgba(99, 102, 241, 0.3);
  padding: 2px 10px;
  border-radius: 9999px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  animation: pa-badge-pulse-indigo 2s ease-in-out infinite;
}
.pa-status-scanning {
  background: rgba(6, 182, 212, 0.15);
  color: #0891b2;
  border: 1px solid rgba(6, 182, 212, 0.3);
  padding: 2px 10px;
  border-radius: 9999px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  animation: pa-badge-pulse-cyan 2s ease-in-out infinite;
}
.pa-status-completed {
  background: rgba(16, 185, 129, 0.15);
  color: #059669;
  border: 1px solid rgba(16, 185, 129, 0.3);
  padding: 2px 10px;
  border-radius: 9999px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.pa-status-exception {
  background: rgba(239, 68, 68, 0.15);
  color: #dc2626;
  border: 1px solid rgba(239, 68, 68, 0.3);
  padding: 2px 10px;
  border-radius: 9999px;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  animation: pa-badge-pulse-red 1.5s ease-in-out infinite;
}
@keyframes pa-badge-pulse-indigo {
