  overflow-y: auto;
  animation: pd-slide-in 0.3s ease-out;
}
@keyframes pd-slide-in {
  from { transform: translateX(100%); } to { transform: translateX(0); }
}

.pd-drawer-header { position: sticky; top: 0; z-index: 10; background: white; dark:bg-gray-900; }
