.mci-channel-card-name { font-size: 13px; font-weight: 600; display: block; }
.mci-channel-card-id { font-size: 11px; color: #94a3b8; }
.mci-channel-card-stats { display: flex; padding: 0; border-bottom: 1px solid #f1f5f9; }
.mci-channel-stat {
  flex: 1; text-align: center; padding: 14px 8px;
  border-right: 1px solid #f1f5f9;
}
.mci-channel-stat:last-child { border-right: none; }
.mci-channel-stat-value { font-size: 14px; font-weight: 700; display: block; }
.mci-channel-stat-label { font-size: 10px; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.3px; }
.mci-channel-card-toggles {
  display: flex; gap: 4px; padding: 10px 16px; flex-wrap: wrap;
  border-bottom: 1px solid #f1f5f9;
}
.mci-toggle {
