.mci-channel-card-footer {
  display: flex; gap: 12px; padding: 10px 16px; font-size: 11px; color: #64748b; flex-wrap: wrap;
}
.mci-channel-footer-item { display: flex; align-items: center; gap: 3px; }

/* Progress Bar */
.mci-progress-bar { display: flex; align-items: center; gap: 6px; justify-content: center; }
.mci-progress-fill { width: 50px; height: 6px; border-radius: 3px; background: #e2e8f0; overflow: hidden; }
.mci-progress-fill > span { display: none; }
.mci-progress-bar > span:last-child { font-size: 12px; font-weight: 600; }

/* Rating */
.mci-rating-inline { display: flex; align-items: center; justify-content: center; gap: 3px; font-size: 12px; font-weight: 600; }

/* Sync Actions */
.mci-sync-actions { display: flex; gap: 4px; }
.mci-sync-btn {
