  z-index: 1000; opacity: 0; visibility: hidden;
  transition: all 0.3s ease; backdrop-filter: blur(4px);
}
.mci-drawer-open { opacity: 1; visibility: visible; }
.mci-drawer {
  position: fixed; top: 0; right: -560px; width: 560px; height: 100vh;
  background: #fff; box-shadow: -8px 0 32px rgba(0,0,0,0.12);
  transition: right 0.3s ease; z-index: 1001;
  display: flex; flex-direction: column; overflow: hidden;
}
.mci-drawer-open .mci-drawer { right: 0; }
.mci-drawer-header { padding: 20px 24px 16px; flex-shrink: 0; }
