}
.mci-drawer-close:hover { background: rgba(255,255,255,0.3); }
.mci-drawer-badges { display: flex; gap: 6px; flex-wrap: wrap; }
.mci-channel-badge {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 3px 10px; border-radius: 4px; font-size: 11px; font-weight: 600;
}
.mci-channel-badge-dot { width: 8px; height: 8px; border-radius: 50%; }
.mci-drawer-content { flex: 1; overflow-y: auto; padding: 20px 24px; }
.mci-drawer-section { margin-bottom: 20px; }
.mci-drawer-section-title { font-size: 13px; font-weight: 600; color: #475569; margin: 0 0 10px; text-transform: uppercase; letter-spacing: 0.5px; }
.mci-drawer-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.mci-drawer-field { display: flex; flex-direction: column; gap: 3px; }
.mci-drawer-field-label { font-size: 11px; color: #94a3b8; }
.mci-drawer-field-value { font-size: 13px; font-weight: 500; color: #1e293b; }

/* Financial Card */
.mci-drawer-financial {
  background: #f8fafc; border-radius: 10px; padding: 14px;
  border: 1px solid #e2e8f0;
}
.mci-financial-row {
  display: flex; justify-content: space-between; align-items: center;
  padding: 6px 0; font-size: 13px; color: #64748b;
  border-bottom: 1px solid #f1f5f9;
}
.mci-financial-row:last-child { border-bottom: none; }
.mci-financial-total {
  font-weight: 600; color: #1e293b; font-size: 15px;
  border-top: 2px solid #e2e8f0; border-bottom: none;
  margin-top: 4px; padding-top: 10px;
}
.mci-financial-value { font-weight: 600; color: #1e293b; }

/* Timeline */
.mci-timeline { display: flex; flex-direction: column; gap: 0; }
.mci-timeline-item {
  display: flex; gap: 12px; align-items: flex-start;
  padding-bottom: 16px; position: relative;
}
.mci-timeline-item:not(:last-child)::after {
  content: ''; position: absolute; left: 6px; top: 16px;
  width: 2px; height: calc(100% - 16px); background: #e2e8f0;
}
.mci-timeline-dot {
  width: 14px; height: 14px; border-radius: 50%; flex-shrink: 0; margin-top: 2px;
  border: 2px solid #fff; box-shadow: 0 0 0 2px #e2e8f0;
}
.mci-timeline-step { font-size: 12px; font-weight: 600; display: block; }
.mci-timeline-time { font-size: 11px; color: #94a3b8; }

/* Drawer Actions */
.mci-drawer-actions { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; padding-top: 16px; border-top: 1px solid #e2e8f0; }
.mci-drawer-btn {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  padding: 10px 8px; border-radius: 8px; font-size: 11px; font-weight: 500;
  cursor: pointer; transition: all 0.15s; border: 1px solid;
}
.mci-drawer-btn-primary { background: #6366f1; color: #fff; border-color: #6366f1; }
.mci-drawer-btn-primary:hover { background: #4f46e5; }
.mci-drawer-btn-secondary { background: #fff; color: #1e293b; border-color: #e2e8f0; }
.mci-drawer-btn-secondary:hover { background: #f8fafc; border-color: #6366f1; color: #6366f1; }
.mci-drawer-btn-outline { background: #fff; color: #64748b; border-color: #e2e8f0; }
.mci-drawer-btn-outline:hover { background: #fef2f2; border-color: #ef4444; color: #ef4444; }

/* Channel Header */
.mci-ch-header { margin-bottom: 16px; }

/* Responsive */
@media (max-width: 1200px) {
  .mci-kpi-grid { grid-template-columns: repeat(3, 1fr); }
  .mci-charts-row { grid-template-columns: 1fr; }
  .mci-alerts-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .mci-kpi-grid { grid-template-columns: repeat(2, 1fr); }
  .mci-header { flex-direction: column; }
  .mci-tabs { overflow-x: auto; -webkit-overflow-scrolling: touch; }
  .mci-channel-grid { grid-template-columns: 1fr; }
  .mci-alerts-grid { grid-template-columns: 1fr; }
  .mci-drawer { width: 100%; right: -100%; }
  .mci-drawer-actions { grid-template-columns: repeat(2, 1fr); }
}
