/* Responsive */
@media (max-width: 1200px) {
  .sp-kpi-grid { grid-template-columns: repeat(3, 1fr); }
  .sp-alerts-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .sp-kpi-grid { grid-template-columns: repeat(2, 1fr); }
