  .sp-alerts-grid { grid-template-columns: repeat(2, 1fr); }
  .sp-dir-grid { grid-template-columns: 1fr; }
  .sp-drawer-info-grid { grid-template-columns: 1fr; }
  .sp-financial-grid { grid-template-columns: 1fr; }
  .sp-timeline { flex-direction: column; gap: 16px; }
  .sp-timeline::before { display: none; }
