.scf-header-right { display: flex; align-items: center; gap: 16px; }
.scf-header-stat { display: flex; align-items: center; gap: 6px; font-size: 13px; color: #94a3b8; padding: 6px 12px; background: #0f172a80; border-radius: 8px; border: 1px solid #334155; }
.scf-header-stat svg { color: #10b981; }

/* Tabs */
.scf-tabs { display: flex; gap: 4px; padding: 4px; background: #1e293b; border-radius: 12px; border: 1px solid #334155; overflow-x: auto; }
.scf-tab { flex: 1; min-width: 130px; padding: 10px 16px; font-size: 13px; font-weight: 500; color: #94a3b8; background: transparent; border: none; border-radius: 8px; cursor: pointer; transition: all 0.2s; white-space: nowrap; }
.scf-tab:hover { color: #e2e8f0; background: #334155; }
.scf-tab.active { color: #fff; background: linear-gradient(135deg, #10b981, #059669); font-weight: 600; box-shadow: 0 2px 8px rgba(16, 185, 129, 0.3); }

.scf-content { flex: 1; }

/* KPI Grid */
.scf-kpi-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 12px; }
.scf-kpi-card { display: flex; align-items: center; gap: 12px; padding: 14px 16px; background: #1e293b; border: 1px solid #334155; border-radius: 10px; position: relative; transition: border-color 0.2s; }
.scf-kpi-card:hover { border-color: #475569; }
