.wdt-filter-pills { display: flex; gap: 4px; flex-wrap: wrap; }
.wdt-pill { padding: 5px 12px; border: 1px solid #e2e8f0; border-radius: 6px; font-size: 11px; font-weight: 500; cursor: pointer; background: #fff; color: #64748b; transition: all 0.15s; white-space: nowrap; }
.wdt-pill:hover { border-color: #14b8a6; color: #14b8a6; }
.wdt-pill-active { background: #14b8a6; color: #fff; border-color: #14b8a6; }
.wdt-count-badge { font-size: 11px; font-weight: 600; color: #64748b; background: #f1f5f9; padding: 3px 10px; border-radius: 12px; }

/* Zone Grid */
.wdt-zone-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 12px; }
.wdt-zone-card { background: #fff; border-radius: 10px; border: 1px solid #e2e8f0; padding: 14px; cursor: pointer; transition: all 0.2s; }
.wdt-zone-card:hover { transform: translateY(-2px); box-shadow: 0 6px 16px rgba(0,0,0,0.08); border-color: #14b8a6; }
.wdt-zone-card.wdt-temp-alert { border-color: #fca5a5; }
.wdt-zone-card.wdt-hum-alert { box-shadow: inset 0 0 0 1px rgba(245,158,11,0.3); }
.wdt-zone-card-header { display: flex; align-items: flex-start; gap: 8px; margin-bottom: 10px; }
.wdt-zone-type-dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; margin-top: 4px; }
.wdt-zone-card-title { flex: 1; }
.wdt-zone-name { font-size: 13px; font-weight: 600; color: #0f172a; }
.wdt-zone-warehouse { font-size: 11px; color: #94a3b8; }
.wdt-zone-type-badge { font-size: 10px; font-weight: 600; padding: 2px 8px; border-radius: 4px; white-space: nowrap; }
.wdt-zone-metrics { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-bottom: 10px; }
.wdt-zone-metric { text-align: center; padding: 6px 4px; background: #f8fafc; border-radius: 6px; }
.wdt-zm-label { display: flex; align-items: center; justify-content: center; gap: 3px; font-size: 10px; color: #94a3b8; font-weight: 500; margin-bottom: 2px; }
.wdt-zm-value { font-size: 16px; font-weight: 700; color: #0f172a; }
.wdt-zm-target { font-size: 9px; color: #94a3b8; margin-top: 1px; }
.wdt-alert-val { color: #f43f5e !important; font-weight: 800 !important; }
.wdt-zone-bottom { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding-top: 8px; border-top: 1px solid #f1f5f9; }
.wdt-zone-util { display: flex; align-items: center; gap: 6px; font-size: 10px; color: #64748b; }
.wdt-util-bar { flex: 1; height: 4px; background: #f1f5f9; border-radius: 2px; overflow: hidden; }
.wdt-util-fill { height: 100%; border-radius: 2px; }
.wdt-zone-occupancy { display: flex; flex-direction: column; gap: 2px; font-size: 10px; color: #94a3b8; }

/* Status */
.wdt-status-badge { font-size: 10px; font-weight: 600; padding: 3px 8px; border-radius: 4px; white-space: nowrap; }
.wdt-status-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; margin-right: 4px; vertical-align: middle; }

