.wdt-txn-table-wrap { background: #fff; border-radius: 10px; border: 1px solid #e2e8f0; overflow: auto; }
.wdt-txn-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.wdt-txn-table thead th { padding: 8px 10px; text-align: left; font-size: 10px; font-weight: 600; color: #64748b; text-transform: uppercase; letter-spacing: 0.5px; background: #f8fafc; border-bottom: 1px solid #e2e8f0; position: sticky; top: 0; }
.wdt-txn-table tbody tr { border-bottom: 1px solid #f1f5f9; transition: background 0.15s; }
