.wdt-txn-id { font-family: 'Courier New', monospace; font-size: 11px; color: #14b8a6; font-weight: 600; }
.wdt-sensor-name-cell { display: flex; align-items: center; gap: 6px; }
.wdt-sensor-type-icon { color: #14b8a6; flex-shrink: 0; }
.wdt-sensor-type-badge { font-size: 10px; font-weight: 600; padding: 2px 6px; border-radius: 4px; background: #f0fdfa; color: #14b8a6; }
