.wdt-signal-cell { display: flex; align-items: center; gap: 4px; font-size: 11px; }
.wdt-protocol-badge { font-size: 10px; font-weight: 500; padding: 2px 6px; border-radius: 4px; background: #f5f3ff; color: #7c3aed; }
.wdt-view-btn { background: none; border: none; cursor: pointer; color: #14b8a6; padding: 4px; border-radius: 4px; display: flex; align-items: center; }
