.wdt-page-dots { padding: 0 4px; color: #94a3b8; }

/* Equipment Grid */
.wdt-equip-tab .wdt-kpi-sm { grid-template-columns: repeat(5, 1fr); }
.wdt-equip-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 12px; }
.wdt-equip-card { background: #fff; border-radius: 10px; border: 1px solid #e2e8f0; padding: 14px; cursor: pointer; transition: all 0.2s; }
