.wdt-equip-card-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 4px; }
.wdt-equip-name { font-size: 13px; font-weight: 600; color: #0f172a; }
.wdt-equip-meta { font-size: 11px; color: #94a3b8; margin-bottom: 10px; }
