.agv-station-stats { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 12px; }
.agv-station-stat { display: flex; align-items: center; gap: 4px; font-size: 11px; color: #94a3b8; }
.agv-card-action-btn { width: 100%; padding: 8px; background: #06b6d415; border: 1px solid #06b6d430; color: #06b6d4; border-radius: 8px; cursor: pointer; font-size: 12px; display: flex; align-items: center; justify-content: center; gap: 6px; transition: all 0.2s; }
.agv-card-action-btn:hover { background: #06b6d4; color: #fff; }

/* Section header */
.agv-section-header { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
.agv-section-title { font-size: 16px; font-weight: 600; color: #e2e8f0; margin: 0; }

/* Path grid */
.agv-path-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 12px; margin-bottom: 24px; }
.agv-path-card { background: #0f172a; border: 1px solid #1e293b; border-radius: 10px; padding: 14px; border-left: 3px solid; transition: transform 0.2s; }
