.agv-alert-icon { width: 36px; height: 36px; border-radius: 8px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.agv-alert-body { flex: 1; min-width: 0; }
.agv-alert-title { font-size: 13px; font-weight: 600; color: #e2e8f0; margin-bottom: 4px; }
.agv-alert-msg { font-size: 12px; color: #94a3b8; margin-bottom: 6px; }
.agv-alert-meta { display: flex; gap: 12px; font-size: 11px; color: #64748b; flex-wrap: wrap; }
.agv-alert-value { color: #94a3b8; }
.agv-alert-ack { padding: 2px 8px; border-radius: 10px; font-size: 10px; font-weight: 600; }
.agv-ack-yes { background: #22c55e20; color: #22c55e; }
.agv-ack-no { background: #f59e0b20; color: #f59e0b; }

/* Drawer overlay */
.agv-drawer-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.6); z-index: 100; animation: agv-overlayIn 0.25s; }
@keyframes agv-overlayIn { from { opacity: 0; } to { opacity: 1; } }
.agv-drawer-panel { position: fixed; top: 0; right: 0; width: 480px; max-width: 90vw; height: 100vh; background: #0f172a; border-left: 1px solid #1e293b; z-index: 101; display: flex; flex-direction: column; animation: agv-slideIn 0.3s ease; overflow: hidden; }
@keyframes agv-slideIn { from { transform: translateX(100%); } to { transform: translateX(0); } }

/* Drawer header */
