.saf-clock-text { font-size: 13px; color: #94a3b8; font-variant-numeric: tabular-nums; }

.saf-tabs { display: flex; gap: 4px; margin-bottom: 20px; background: #0f172a; border-radius: 10px; padding: 4px; border: 1px solid #1e293b; overflow-x: auto; }
.saf-tab { padding: 10px 18px; border: none; background: transparent; color: #64748b; font-size: 13px; font-weight: 500; cursor: pointer; border-radius: 8px; transition: all 0.2s; white-space: nowrap; }
.saf-tab:hover { color: #e2e8f0; background: #1e293b; }
