.saf-kpi-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 12px; margin-bottom: 20px; }
.saf-kpi-card { background: #0f172a; border: 1px solid #1e293b; border-radius: 10px; padding: 16px; display: flex; align-items: center; gap: 14px; border-top: 3px solid; transition: transform 0.2s, box-shadow 0.2s; }
