.saf-filter-row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin-bottom: 16px; }
.saf-search-box { flex: 1; min-width: 240px; }
.saf-search-input { width: 100%; padding: 9px 14px; background: #0f172a; border: 1px solid #334155; border-radius: 8px; color: #e2e8f0; font-size: 13px; outline: none; transition: border-color 0.2s; box-sizing: border-box; }
.saf-search-input:focus { border-color: #ef4444; }
