.saf-filter-pills { display: flex; gap: 4px; flex-wrap: wrap; }
.saf-pill { padding: 6px 12px; border: 1px solid #334155; background: transparent; color: #94a3b8; font-size: 12px; border-radius: 6px; cursor: pointer; transition: all 0.2s; }
.saf-pill:hover { border-color: #64748b; color: #e2e8f0; }
.saf-pill-active { background: #ef4444 !important; border-color: #ef4444 !important; color: #fff !important; }

.saf-fleet-stats { display: flex; gap: 20px; padding: 10px 16px; background: #0f172a; border: 1px solid #1e293b; border-radius: 8px; margin-bottom: 12px; font-size: 12px; color: #64748b; }
.saf-fleet-stats b { color: #e2e8f0; }

.saf-table-wrapper { overflow-x: auto; background: #0f172a; border: 1px solid #1e293b; border-radius: 10px; margin-bottom: 12px; }
.saf-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.saf-table thead { background: #1e293b; }
.saf-table th { padding: 10px 12px; text-align: left; color: #94a3b8; font-weight: 600; font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 1px solid #334155; white-space: nowrap; }
.saf-th-sortable { cursor: pointer; user-select: none; display: flex; align-items: center; gap: 4px; }
