.saf-bar-text { font-size: 11px; color: #94a3b8; }
.saf-view-btn { padding: 5px 10px; background: #ef444420; border: 1px solid #ef444440; color: #ef4444; border-radius: 6px; cursor: pointer; display: flex; align-items: center; transition: all 0.2s; }
