/* Audit grid */
.saf-audit-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 14px; }
.saf-audit-card { background: #0f172a; border: 1px solid #1e293b; border-radius: 12px; padding: 16px; border-top: 3px solid; transition: transform 0.2s, box-shadow 0.2s; }
