.saf-progress-track { width: 100%; height: 8px; background: #1e293b; border-radius: 4px; overflow: hidden; }
.saf-progress-fill { height: 100%; border-radius: 4px; transition: width 0.5s; }
.saf-audit-finds { display: flex; align-items: center; gap: 4px; font-size: 11px; color: #ef4444; margin-bottom: 10px; }
.saf-audit-meta { display: flex; gap: 12px; font-size: 11px; color: #64748b; margin-bottom: 10px; flex-wrap: wrap; }
.saf-card-action-btn { width: 100%; padding: 8px; background: #06b6d415; border: 1px solid #06b6d430; color: #06b6d4; border-radius: 8px; cursor: pointer; font-size: 12px; display: flex; align-items: center; justify-content: center; gap: 6px; transition: all 0.2s; }
.saf-card-action-btn:hover { background: #06b6d4; color: #fff; }

/* Section header */
.saf-section-header { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
.saf-section-title { font-size: 16px; font-weight: 600; color: #e2e8f0; margin: 0; }

/* Training grid */
.saf-training-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 14px; }
.saf-training-card { background: #0f172a; border: 1px solid #1e293b; border-radius: 12px; padding: 16px; border-left: 3px solid; transition: transform 0.2s; }
.saf-training-card:hover { transform: translateY(-1px); }
.saf-training-header { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.saf-training-name { font-size: 13px; font-weight: 600; color: #e2e8f0; }
.saf-training-type { font-size: 10px; font-weight: 600; text-transform: uppercase; margin-left: auto; }
.saf-training-meta { display: flex; gap: 10px; font-size: 11px; color: #64748b; flex-wrap: wrap; margin-bottom: 8px; }
.saf-training-cert { background: #8b5cf620; color: #a78bfa; padding: 2px 8px; border-radius: 8px; font-size: 10px; }
.saf-training-progress { display: flex; gap: 12px; font-size: 11px; color: #94a3b8; margin-bottom: 8px; }
.saf-training-status { display: inline-block; padding: 3px 10px; border-radius: 12px; font-size: 11px; font-weight: 600; text-transform: capitalize; }

/* Inspection grid */
.saf-insp-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 14px; }
.saf-insp-card { background: #0f172a; border: 1px solid #1e293b; border-radius: 12px; padding: 16px; border-left: 3px solid; transition: transform 0.2s; }
.saf-insp-card:hover { transform: translateY(-1px); }
.saf-insp-header { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.saf-insp-id { font-size: 14px; font-weight: 700; color: #e2e8f0; }
.saf-insp-status { padding: 2px 8px; border-radius: 10px; font-size: 10px; font-weight: 600; text-transform: capitalize; }
.saf-insp-name { font-size: 12px; color: #94a3b8; margin-bottom: 6px; }
.saf-insp-meta { display: flex; gap: 12px; font-size: 11px; color: #64748b; margin-bottom: 8px; }
.saf-insp-score-row { display: flex; gap: 8px; align-items: center; font-size: 13px; color: #cbd5e1; margin-bottom: 6px; }
.saf-insp-score { font-size: 18px; font-weight: 700; }
.saf-insp-finding { font-size: 11px; color: #94a3b8; background: #1e293b40; padding: 6px 10px; border-radius: 6px; }

/* Drawer */
.saf-drawer-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.6); z-index: 100; animation: saf-overlayIn 0.25s; }
@keyframes saf-overlayIn { from { opacity: 0; } to { opacity: 1; } }
.saf-drawer-panel { position: fixed; top: 0; right: 0; width: 480px; max-width: 90vw; height: 100vh; background: #0f172a; border-left: 1px solid #1e293b; z-index: 101; display: flex; flex-direction: column; animation: saf-slideIn 0.3s ease; overflow: hidden; }
@keyframes saf-slideIn { from { transform: translateX(100%); } to { transform: translateX(0); } }
.saf-drawer-header { padding: 20px 24px 16px; flex-shrink: 0; }
.saf-drawer-header-top { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12px; }
.saf-drawer-header-info { display: flex; align-items: center; gap: 12px; }
.saf-drawer-header-icon { color: #fff; }
.saf-drawer-title { font-size: 20px; font-weight: 700; color: #fff; }
.saf-drawer-subtitle { font-size: 12px; color: rgba(255,255,255,0.7); margin-top: 2px; }
.saf-drawer-close { background: rgba(255,255,255,0.15); border: none; color: #fff; border-radius: 6px; width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; cursor: pointer; }
.saf-drawer-close:hover { background: rgba(255,255,255,0.25); }
.saf-drawer-badges { display: flex; gap: 6px; }
.saf-drawer-badge { padding: 4px 12px; border-radius: 12px; font-size: 11px; font-weight: 600; }
.saf-drawer-body { flex: 1; overflow-y: auto; padding: 20px 24px; }
.saf-drawer-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; }
.saf-drawer-field { background: #1e293b40; border-radius: 8px; padding: 10px 12px; display: flex; flex-direction: column; gap: 3px; }
.saf-drawer-label { font-size: 10px; color: #64748b; text-transform: uppercase; letter-spacing: 0.5px; }
.saf-drawer-value { font-size: 13px; color: #e2e8f0; font-weight: 500; }
.saf-drawer-section-title { font-size: 13px; font-weight: 600; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.8px; margin: 16px 0 10px; padding-bottom: 6px; border-bottom: 1px solid #1e293b; }
.saf-drawer-desc { font-size: 13px; color: #94a3b8; line-height: 1.6; margin: 0 0 12px; padding: 12px; background: #1e293b40; border-radius: 8px; }
.saf-drawer-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 20px; padding-top: 16px; border-top: 1px solid #1e293b; }
.saf-action-btn { padding: 9px 16px; border-radius: 8px; font-size: 12px; font-weight: 500; cursor: pointer; display: flex; align-items: center; gap: 6px; transition: all 0.2s; border: none; }
.saf-action-primary { background: linear-gradient(135deg, #ef4444, #dc2626); color: #fff; box-shadow: 0 2px 8px rgba(239,68,68,0.3); }
.saf-action-primary:hover { box-shadow: 0 4px 14px rgba(239,68,68,0.4); transform: translateY(-1px); }
.saf-action-secondary { background: #1e293b; border: 1px solid #334155; color: #cbd5e1; }
.saf-action-secondary:hover { border-color: #ef4444; color: #ef4444; }
.saf-action-ghost { background: transparent; border: 1px solid #334155; color: #64748b; }
.saf-action-ghost:hover { border-color: #64748b; color: #cbd5e1; }

@media (max-width: 768px) {
  .saf-container { padding: 12px; }
  .saf-page-header { flex-direction: column; gap: 12px; }
  .saf-kpi-grid { grid-template-columns: repeat(2, 1fr); }
  .saf-charts-row { grid-template-columns: 1fr; }
  .saf-audit-grid { grid-template-columns: 1fr; }
  .saf-training-grid { grid-template-columns: 1fr; }
  .saf-insp-grid { grid-template-columns: 1fr; }
  .saf-drawer-panel { width: 100vw; }
  .saf-drawer-grid { grid-template-columns: 1fr; }
}
/* ═══════════════════════════════════════════════════════════════════════════════
   R169: Goods-to-Person (GTP) Picking System — gtp-* prefix
   Theme: Sky Blue (#0ea5e9) + Violet (#8b5cf6) + Amber (#f59e0b)
   ═══════════════════════════════════════════════════════════════════════════════ */

/* ── Root & Layout ──────────────────────────────────────────────────────────── */
.gtp-root { padding: 1.25rem; min-height: 100vh; background: linear-gradient(180deg, #0f172a 0%, #1a1f3a 100%); color: #e2e8f0; font-family: 'Inter', system-ui, -apple-system, sans-serif; }
.gtp-space-y-6 > * + * { margin-top: 1.5rem; }
.gtp-space-y-4 > * + * { margin-top: 1rem; }

/* ── Clock Bar ─────────────────────────────────────────────────────────────── */
.gtp-clock-bar { display: flex; align-items: center; gap: 1.25rem; padding: 0.75rem 1.25rem; background: rgba(14, 165, 233, 0.08); border: 1px solid rgba(14, 165, 233, 0.2); border-radius: 10px; backdrop-filter: blur(8px); }
.gtp-clock-label { display: flex; align-items: center; gap: 0.5rem; font-size: 0.8rem; color: #0ea5e9; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; }
.gtp-clock-time { font-size: 1.5rem; font-weight: 700; color: #f1f5f9; font-variant-numeric: tabular-nums; }
.gtp-clock-date { margin-left: auto; font-size: 0.8rem; color: #94a3b8; }

/* ── KPI Grid ──────────────────────────────────────────────────────────────── */
.gtp-kpi-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.gtp-kpi-card { display: flex; align-items: center; gap: 1rem; padding: 1.25rem; background: rgba(30, 41, 59, 0.85); border: 1px solid #334155; border-left: 4px solid; border-radius: 10px; transition: all 0.2s; }
.gtp-kpi-card:hover { background: rgba(30, 41, 59, 1); transform: translateY(-1px); box-shadow: 0 4px 20px rgba(0,0,0,0.3); }
.gtp-kpi-icon { width: 44px; height: 44px; border-radius: 10px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.gtp-kpi-content { flex: 1; }
.gtp-kpi-value { font-size: 1.6rem; font-weight: 700; line-height: 1.2; }
.gtp-kpi-label { font-size: 0.8rem; color: #94a3b8; margin-top: 0.15rem; }
.gtp-kpi-sub { font-size: 0.7rem; color: #64748b; }

/* ── Charts ────────────────────────────────────────────────────────────────── */
.gtp-charts-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.gtp-chart-card { background: rgba(30, 41, 59, 0.85); border: 1px solid #334155; border-radius: 10px; padding: 1.25rem; }
.gtp-chart-title { font-size: 0.9rem; font-weight: 600; color: #e2e8f0; margin-bottom: 1rem; display: flex; align-items: center; gap: 0.5rem; }

/* ── Section Card ──────────────────────────────────────────────────────────── */
.gtp-section-card { background: rgba(30, 41, 59, 0.85); border: 1px solid #334155; border-radius: 10px; padding: 1.25rem; }
.gtp-section-title { font-size: 0.95rem; font-weight: 600; color: #e2e8f0; margin-bottom: 1rem; display: flex; align-items: center; gap: 0.5rem; }

/* ── Zone Grid ─────────────────────────────────────────────────────────────── */
.gtp-zone-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 0.75rem; }
.gtp-zone-card { background: rgba(15, 23, 42, 0.6); border: 1px solid #334155; border-radius: 8px; padding: 0.85rem; }
.gtp-zone-name { font-size: 0.8rem; font-weight: 600; color: #0ea5e9; margin-bottom: 0.5rem; }
.gtp-zone-stats { display: flex; flex-wrap: wrap; gap: 0.6rem; font-size: 0.7rem; color: #94a3b8; margin-bottom: 0.5rem; }
.gtp-zone-stats span { display: flex; align-items: center; gap: 0.25rem; }
.gtp-zone-bar-wrap { display: flex; align-items: center; gap: 0.5rem; margin-top: 0.35rem; }
.gtp-zone-bar-label { font-size: 0.65rem; color: #64748b; width: 50px; flex-shrink: 0; }
.gtp-zone-bar-track { flex: 1; height: 6px; background: #1e293b; border-radius: 3px; overflow: hidden; }
.gtp-zone-bar-fill { height: 100%; border-radius: 3px; transition: width 0.5s; }
.gtp-zone-bar-val { font-size: 0.7rem; color: #e2e8f0; width: 36px; text-align: right; }

/* ── Toolbar ───────────────────────────────────────────────────────────────── */
.gtp-toolbar { display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap; padding: 0.85rem 1rem; background: rgba(30, 41, 59, 0.7); border: 1px solid #334155; border-radius: 10px; }
.gtp-search-wrap { position: relative; flex: 1; min-width: 220px; }
.gtp-search-icon { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: #64748b; }
.gtp-search-input { width: 100%; padding: 0.55rem 0.75rem 0.55rem 2.25rem; background: #0f172a; border: 1px solid #334155; border-radius: 6px; color: #e2e8f0; font-size: 0.8rem; outline: none; transition: border-color 0.2s; }
.gtp-search-input:focus { border-color: #0ea5e9; }
.gtp-filter-pills { display: flex; gap: 0.35rem; flex-wrap: wrap; }
.gtp-pill { padding: 0.3rem 0.65rem; font-size: 0.7rem; background: rgba(51, 65, 85, 0.6); border: 1px solid #475569; border-radius: 14px; color: #94a3b8; cursor: pointer; transition: all 0.2s; white-space: nowrap; }
.gtp-pill:hover { background: rgba(14, 165, 233, 0.15); border-color: #0ea5e9; color: #e2e8f0; }
.gtp-pill-active { background: rgba(14, 165, 233, 0.2); border-color: #0ea5e9; color: #0ea5e9; font-weight: 600; }
.gtp-filter-select { display: flex; align-items: center; gap: 0.4rem; }
.gtp-filter-select select { padding: 0.4rem 0.6rem; background: #0f172a; border: 1px solid #334155; border-radius: 6px; color: #e2e8f0; font-size: 0.75rem; outline: none; cursor: pointer; }
.gtp-filter-select select:focus { border-color: #0ea5e9; }

/* ── Table ────────────────────────────────────────────────────────────────── */
.gtp-table-wrap { overflow-x: auto; background: rgba(30, 41, 59, 0.7); border: 1px solid #334155; border-radius: 10px; }
.gtp-table { width: 100%; border-collapse: collapse; font-size: 0.78rem; }
.gtp-table thead { background: rgba(15, 23, 42, 0.8); }
.gtp-table th { padding: 0.65rem 0.75rem; text-align: left; color: #94a3b8; font-weight: 600; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.03em; border-bottom: 1px solid #334155; white-space: nowrap; }
.gtp-th-sort { cursor: pointer; user-select: none; }
.gtp-th-sort:hover { color: #e2e8f0; }
.gtp-th-content { display: flex; align-items: center; gap: 0.35rem; }
.gtp-table td { padding: 0.55rem 0.75rem; border-bottom: 1px solid rgba(51, 65, 85, 0.5); color: #cbd5e1; white-space: nowrap; }
.gtp-table-row { transition: background 0.15s; }
.gtp-table-row:hover { background: rgba(14, 165, 233, 0.06); }
.gtp-mono { font-family: 'JetBrains Mono', 'Fira Code', monospace; font-size: 0.72rem; color: #0ea5e9; }
