.wlf-chart-card { background: #fff; border-radius: 12px; padding: 16px; box-shadow: 0 1px 4px rgba(0,0,0,0.06); }
.wlf-chart-card h4 { font-size: 13px; font-weight: 600; color: #334155; display: flex; align-items: center; gap: 6px; margin-bottom: 12px; }

/* Tab Content */
.wlf-tab-content { background: #fff; border-radius: 12px; padding: 16px; box-shadow: 0 1px 4px rgba(0,0,0,0.06); min-height: 500px; }

/* Toolbar */
.wlf-toolbar { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; flex-wrap: wrap; }
.wlf-search { display: flex; align-items: center; gap: 8px; background: #f1f5f9; border-radius: 8px; padding: 8px 14px; flex: 1; min-width: 200px; }
.wlf-search input { border: none; background: none; outline: none; font-size: 13px; width: 100%; color: #0f172a; }
.wlf-search svg { color: #94a3b8; flex-shrink: 0; }
.wlf-filters { display: flex; gap: 8px; flex-wrap: wrap; }
.wlf-filters select { padding: 7px 12px; border: 1px solid #e2e8f0; border-radius: 8px; font-size: 12px; color: #334155; background: #fff; cursor: pointer; outline: none; }
.wlf-count { font-size: 12px; color: #64748b; font-weight: 600; margin-left: auto; }

/* Badge */
.wlf-badge { display: inline-block; padding: 2px 10px; border-radius: 6px; font-size: 10px; font-weight: 600; text-transform: capitalize; white-space: nowrap; }
.wlf-zone-badge { display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 10px; background: #ede9fe; color: #7c3aed; font-weight: 600; }
.wlf-shift-tag { display: inline-block; padding: 2px 10px; border-radius: 6px; font-size: 10px; font-weight: 600; text-transform: capitalize; }
.wlf-shift-morning { background: #fef3c7; color: #d97706; }
.wlf-shift-afternoon { background: #fce7f3; color: #db2777; }
.wlf-shift-night { background: #1e293b; color: #e2e8f0; }

/* Table */
.wlf-table-wrap { overflow-x: auto; }
.wlf-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.wlf-table thead th { text-align: left; padding: 10px 12px; background: #f8fafc; color: #475569; font-weight: 600; font-size: 11px; text-transform: uppercase; letter-spacing: 0.3px; cursor: pointer; border-bottom: 2px solid #e2e8f0; white-space: nowrap; user-select: none; }
.wlf-table thead th:hover { color: #0f172a; }
.wlf-sorted-asc::after { content: " ↑"; color: #0ea5e9; }
.wlf-sorted-desc::after { content: " ↓"; color: #0ea5e9; }
.wlf-table tbody tr { border-bottom: 1px solid #f1f5f9; cursor: pointer; transition: background 0.15s; }
.wlf-table tbody tr:hover { background: #f0f9ff; }
.wlf-table td { padding: 10px 12px; color: #334155; white-space: nowrap; }
.wlf-mono { font-family: monospace; font-size: 11px; color: #64748b; }
.wlf-bold { font-weight: 700; color: #0f172a !important; }
.wlf-action-btn { color: #94a3b8; }
.wlf-action-btn:hover { color: #0ea5e9; }

/* Employee cell */
.wlf-emp-cell { display: flex; flex-direction: column; }
.wlf-emp-name { font-size: 12px; font-weight: 600; color: #0f172a; }
.wlf-emp-id { font-size: 10px; color: #94a3b8; font-family: monospace; }

/* Star ratings */
.wlf-stars { display: flex; gap: 1px; }

/* Overall score badge */
.wlf-overall-badge { display: inline-block; padding: 3px 10px; border-radius: 6px; font-size: 12px; font-weight: 700; }

/* Progress bar in cells */
.wlf-bar-cell { display: flex; align-items: center; gap: 8px; }
.wlf-bar { height: 6px; border-radius: 3px; min-width: 4px; transition: width 0.3s; }

/* Pagination */
.wlf-pagination { display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 16px; padding-top: 12px; border-top: 1px solid #f1f5f9; }
.wlf-pagination button { display: flex; align-items: center; justify-content: center; width: 32px; height: 32px; border-radius: 8px; border: 1px solid #e2e8f0; background: #fff; cursor: pointer; color: #475569; transition: all 0.15s; }
.wlf-pagination button:hover:not(:disabled) { border-color: #0ea5e9; color: #0ea5e9; }
.wlf-pagination button:disabled { opacity: 0.4; cursor: not-allowed; }
.wlf-pagination span { font-size: 12px; color: #64748b; font-weight: 600; }

/* Drawer */
.wlf-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.4); z-index: 50; backdrop-filter: blur(2px); }
.wlf-drawer { position: fixed; top: 0; right: 0; width: 480px; max-width: 95vw; height: 100vh; background: #fff; z-index: 51; box-shadow: -4px 0 24px rgba(0,0,0,0.15); display: flex; flex-direction: column; animation: wlf-slideIn 0.25s ease; }
@keyframes wlf-slideIn { from { transform: translateX(100%); } to { transform: translateX(0); } }
.wlf-drawer-header { padding: 16px 20px; display: flex; justify-content: space-between; align-items: flex-start; background: linear-gradient(135deg, #0ea5e9, #8b5cf6); color: #fff; }
.wlf-drawer-header h3 { font-size: 16px; font-weight: 700; display: flex; align-items: center; gap: 8px; margin: 0; }
.wlf-drawer-subtitle { font-size: 11px; opacity: 0.8; }
.wlf-drawer-header button { background: rgba(255,255,255,0.2); border: none; color: #fff; width: 32px; height: 32px; border-radius: 8px; cursor: pointer; display: flex; align-items: center; justify-content: center; }
.wlf-drawer-header button:hover { background: rgba(255,255,255,0.3); }
.wlf-drawer-body { flex: 1; overflow-y: auto; padding: 20px; }

/* Drawer Metrics */
.wlf-drawer-metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 16px; }
.wlf-drawer-metric { background: #f8fafc; border-radius: 10px; padding: 12px; border-left: 3px solid; display: flex; align-items: center; gap: 10px; }
.wlf-metric-icon { color: inherit; opacity: 0.7; }
.wlf-metric-info { display: flex; flex-direction: column; }
.wlf-metric-value { font-size: 14px; font-weight: 700; }
.wlf-metric-label { font-size: 10px; color: #64748b; text-transform: uppercase; letter-spacing: 0.3px; }

/* Drawer Field Grid */
.wlf-drawer-field-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-bottom: 16px; }
.wlf-drawer-field { padding: 10px; background: #f8fafc; border-radius: 8px; }
.wlf-field-label { display: block; font-size: 10px; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.3px; margin-bottom: 3px; font-weight: 600; }
.wlf-field-value { font-size: 13px; color: #0f172a; font-weight: 500; }

/* Drawer Actions */
.wlf-drawer-actions { display: flex; gap: 8px; padding-top: 16px; border-top: 1px solid #e2e8f0; margin-top: 16px; }
.wlf-btn { display: flex; align-items: center; gap: 6px; padding: 8px 16px; border-radius: 8px; font-size: 12px; font-weight: 600; border: none; cursor: pointer; transition: all 0.15s; flex: 1; justify-content: center; }
.wlf-btn-primary { background: #0ea5e9; color: #fff; }
.wlf-btn-primary:hover { background: #0284c7; }
.wlf-btn-secondary { background: #f1f5f9; color: #334155; }
.wlf-btn-secondary:hover { background: #e2e8f0; }
.wlf-btn-accent { background: #8b5cf6; color: #fff; }
.wlf-btn-accent:hover { background: #7c3aed; }

/* Cost Breakdown */
.wlf-cost-breakdown { margin: 16px 0; }
.wlf-cost-breakdown h4 { font-size: 13px; font-weight: 600; color: #334155; display: flex; align-items: center; gap: 6px; margin-bottom: 12px; }
.wlf-cost-bars { display: flex; flex-direction: column; gap: 8px; }
.wlf-cost-bar-row { display: flex; align-items: center; gap: 10px; font-size: 12px; }
.wlf-cost-bar-label { width: 70px; color: #475569; flex-shrink: 0; }
.wlf-cost-bar-track { flex: 1; height: 10px; background: #f1f5f9; border-radius: 5px; overflow: hidden; }
.wlf-cost-bar { height: 100%; border-radius: 5px; transition: width 0.3s; }
.wlf-cost-bar-pct { width: 45px; text-align: right; color: #64748b; font-weight: 600; font-size: 11px; }

/* Skill table wider */
.wlf-skill-table th, .wlf-skill-table td { padding: 8px 10px; }

/* Responsive */
@media (max-width: 768px) {
  .wlf-kpi-grid { grid-template-columns: repeat(2, 1fr); }
  .wlf-charts-grid { grid-template-columns: 1fr; }
  .wlf-drawer-field-grid { grid-template-columns: 1fr; }
  .wlf-drawer-metrics { grid-template-columns: 1fr; }
  .wlf-toolbar { flex-direction: column; align-items: stretch; }
  .wlf-count { margin-left: 0; }
}
