/* ============================================================================
 * R202: Warehouse Operations Command Center (woc-*) — Enhanced CSS
 * Theme: Deep Navy #0f172a + Cyan #06b6d4 + Orange #f97316 + Emerald #10b981 + Slate #64748b
 * ============================================================================ */

/* --- Tab Active State: Navy→Cyan gradient with glow --- */
.woc-root [data-state="active"][role="tab"] {
  background: linear-gradient(135deg, #0f172a, #0e7490) !important;
  color: #ecfeff !important;
  box-shadow: 0 0 16px rgba(6, 182, 212, 0.35), 0 2px 8px rgba(6, 182, 212, 0.2);
  position: relative;
}
.woc-root [data-state="active"][role="tab"]::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(6,182,212,0.15), transparent);
  pointer-events: none;
}

/* --- KPI Card: 8 distinct border-left colors + radial corner glow --- */
.woc-kpi-card:nth-child(1) { border-left: 3px solid #06b6d4; }
.woc-kpi-card:nth-child(2) { border-left: 3px solid #f97316; }
.woc-kpi-card:nth-child(3) { border-left: 3px solid #10b981; }
.woc-kpi-card:nth-child(4) { border-left: 3px solid #8b5cf6; }
.woc-kpi-card:nth-child(5) { border-left: 3px solid #f59e0b; }
.woc-kpi-card:nth-child(6) { border-left: 3px solid #ef4444; }
.woc-kpi-card:nth-child(7) { border-left: 3px solid #64748b; }
.woc-kpi-card:nth-child(8) { border-left: 3px solid #ec4899; }
.woc-kpi-card {
  border-radius: 10px;
  position: relative;
  overflow: hidden;
  animation: woc-kpi-fade-up 0.5s ease-out both;
  transition: transform 0.2s, box-shadow 0.2s;
}
.woc-kpi-card:nth-child(1) { animation-delay: 0ms; }
.woc-kpi-card:nth-child(2) { animation-delay: 50ms; }
.woc-kpi-card:nth-child(3) { animation-delay: 100ms; }
.woc-kpi-card:nth-child(4) { animation-delay: 150ms; }
.woc-kpi-card:nth-child(5) { animation-delay: 200ms; }
.woc-kpi-card:nth-child(6) { animation-delay: 250ms; }
.woc-kpi-card:nth-child(7) { animation-delay: 300ms; }
.woc-kpi-card:nth-child(8) { animation-delay: 350ms; }
.woc-kpi-card::before {
  content: '';
  position: absolute;
  top: -30px;
  right: -30px;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--kpi-glow, rgba(6,182,212,0.08)), transparent 70%);
  pointer-events: none;
}
.woc-kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(6,182,212,0.12);
}
@keyframes woc-kpi-fade-up {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- KPI Value counter animation --- */
.woc-kpi-card .tabular-nums {
  animation: woc-counter-scale 0.4s ease-out;
  font-variant-numeric: tabular-nums;
}
@keyframes woc-counter-scale {
  from { transform: scale(0.85); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

/* --- Dock Card: border + hover lift --- */
.woc-dock-card {
  border-radius: 10px;
  border: 1px solid rgba(100,116,139,0.15);
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
}
.woc-dock-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(6,182,212,0.1);
  border-color: rgba(6,182,212,0.3);
}

/* --- Utilization Bar: fill transition --- */
.woc-util-fill {
  transition: width 0.8s ease-out;
  border-radius: 4px;
  position: relative;
}
.woc-util-track {
  border-radius: 4px;
  background: rgba(100,116,139,0.12);
}

/* --- Pipeline Stage: dot + line transitions --- */
.woc-stage-dot {
  transition: transform 0.2s, box-shadow 0.2s;
  border-radius: 50%;
}
.woc-stage-dot:hover {
  transform: scale(1.3);
}
.woc-stage-done .woc-stage-dot {
  box-shadow: 0 0 8px rgba(16,185,129,0.4);
}
.woc-stage-line {
  transition: background 0.3s;
}
.woc-stage-line-done {
  background: #10b981;
}
.woc-stage-line-pending {
  background: rgba(100,116,139,0.2);
}

/* --- Pill Badge: shimmer animation --- */
.woc-pill {
  animation: woc-badge-shimmer 3s ease-in-out infinite;
  animation-delay: 1.2s;
  position: relative;
  overflow: hidden;
}
.woc-pill::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.15), transparent);
  animation: woc-shimmer-sweep 3s ease-in-out infinite;
  animation-delay: 1.2s;
}
@keyframes woc-shimmer-sweep {
  0% { left: -100%; }
  50% { left: 100%; }
  100% { left: 100%; }
}

/* --- P1 Severity: red pulse animation --- */
.woc-p1-pulse {
  animation: woc-p1-blink 1.2s ease-in-out infinite;
}
@keyframes woc-p1-blink {
  0%, 100% { opacity: 1; box-shadow: 0 0 4px rgba(239,68,68,0.3); }
  50% { opacity: 0.65; box-shadow: 0 0 12px rgba(239,68,68,0.6); }
}

/* --- SLA Countdown: urgent pulse (< 25% red) --- */
.woc-sla-urgent {
  animation: woc-sla-urgent-pulse 1.5s ease-in-out infinite;
}
@keyframes woc-sla-urgent-pulse {
  0%, 100% { color: #ef4444; }
  50% { color: #fca5a5; }
}

/* --- MTTR Tile --- */
.woc-mttr-tile {
  border-radius: 8px;
  position: relative;
  overflow: hidden;
}
.woc-mttr-tile::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, #f97316, #ef4444);
}

/* --- Worker Availability Tile --- */
.woc-avail-card {
  border-radius: 10px;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s;
}
.woc-avail-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(6,182,212,0.1);
}
.woc-avail-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, #06b6d4, #10b981);
}

/* --- Drawer Header --- */
.woc-drawer-header {
  border-radius: 12px;
  padding: 16px 20px;
  color: #fff;
}

/* --- Row Striping --- */
.woc-data-row:nth-child(even) {
  background: rgba(100,116,139,0.03);
}

/* --- Sort Header: hover + active --- */
.woc-sort-header {
  transition: background 0.15s, transform 0.15s;
  cursor: pointer;
}
.woc-sort-header:hover {
  background: rgba(6,182,212,0.08);
}
.woc-sort-header[aria-sort="ascending"],
.woc-sort-header[aria-sort="descending"] {
  background: rgba(6,182,212,0.12);
  transform: scale(0.98);
}

/* --- Action Buttons --- */
.woc-action-btn {
  transition: all 0.15s;
}
.woc-action-btn:hover {
  transform: scale(1.03);
  background: rgba(6,182,212,0.1);
  border-color: rgba(6,182,212,0.4);
  color: #06b6d4;
}

/* --- Table Row Hover per-tab tint --- */
.woc-tab-0-row:hover { background: rgba(6,182,212,0.04); }
.woc-tab-1-row:hover { background: rgba(15,23,42,0.04); }
.woc-tab-2-row:hover { background: rgba(6,182,212,0.04); }
.woc-tab-3-row:hover { background: rgba(249,115,22,0.04); }
.woc-tab-4-row:hover { background: rgba(16,185,129,0.04); }
.woc-tab-5-row:hover { background: rgba(239,68,68,0.04); }

/* --- Chart Card: glow on hover --- */
.woc-chart-card {
  border-radius: 10px;
  transition: box-shadow 0.2s;
}
.woc-chart-card:hover {
  box-shadow: 0 0 20px rgba(6,182,212,0.08);
}

/* --- SVG Ring: draw transition --- */
.woc-ring-progress {
  transition: stroke-dashoffset 1s ease-out;
}

/* --- Responsive Grid --- */
.woc-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
@media (max-width: 1024px) {
  .woc-kpi-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .woc-kpi-grid { grid-template-columns: 1fr; }
}

/* --- Custom Scrollbar for command center --- */
.woc-root ::-webkit-scrollbar { width: 6px; height: 6px; }
.woc-root ::-webkit-scrollbar-track { background: rgba(15,23,42,0.05); border-radius: 3px; }
.woc-root ::-webkit-scrollbar-thumb { background: rgba(100,116,139,0.3); border-radius: 3px; }
.woc-root ::-webkit-scrollbar-thumb:hover { background: rgba(100,116,139,0.5); }

/* --- Sheet Content Transition --- */
.woc-drawer-header + div {
  animation: woc-sheet-fade 0.25s ease-out;
}
@keyframes woc-sheet-fade {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

