/* ============================================================================
 * R205: Multi-Modal Transport Corridor (mtc-*) — Enhanced CSS
 * Theme: Deep Sky #0369a1 + Teal #0d9488 + Amber #d97706 + Violet #7c3aed + Slate #475569 + Emerald #059669
 * ============================================================================ */

/* --- Root Container --- */
.mtc-root { font-family: 'Inter', system-ui, -apple-system, sans-serif; }
.mtc-root * { scrollbar-width: thin; scrollbar-color: rgba(3,105,161,0.2) transparent; }

/* --- KPI Cards: Multi-tone left border with subtle gradient background --- */
.mtc-kpi-card { border-left: 4px solid transparent; border-radius: 8px; overflow: hidden; transition: all 0.25s ease; position: relative; }
.mtc-kpi-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: linear-gradient(90deg, #0369a1, #0d9488, #d97706); opacity: 0; transition: opacity 0.3s ease; }
.mtc-kpi-card:nth-child(1) { border-left-color: #0369a1; }
.mtc-kpi-card:nth-child(2) { border-left-color: #0d9488; }
.mtc-kpi-card:nth-child(3) { border-left-color: #059669; }
.mtc-kpi-card:nth-child(4) { border-left-color: #dc2626; }
.mtc-kpi-card:nth-child(5) { border-left-color: #7c3aed; }
.mtc-kpi-card:nth-child(6) { border-left-color: #d97706; }
.mtc-kpi-card:nth-child(7) { border-left-color: #be123c; }
.mtc-kpi-card:nth-child(8) { border-left-color: #475569; }
.mtc-kpi-card:hover { transform: translateY(-2px); box-shadow: 0 4px 16px rgba(3,105,161,0.12); }
.mtc-kpi-card:hover::before { opacity: 1; }

/* --- Chart Cards --- */
.mtc-chart-card { border-radius: 10px; overflow: hidden; transition: all 0.25s ease; border: 1px solid rgba(3,105,161,0.08); }
.mtc-chart-card:hover { box-shadow: 0 6px 24px rgba(3,105,161,0.1); border-color: rgba(3,105,161,0.2); }

/* --- Pills & Badges --- */
.mtc-pill { transition: all 0.2s ease; box-shadow: 0 1px 2px rgba(0,0,0,0.05); }
.mtc-pill:hover { transform: scale(1.03); box-shadow: 0 2px 6px rgba(0,0,0,0.1); }
.mtc-status-badge { letter-spacing: 0.02em; }
.mtc-mode-badge { gap: 4px; border-color: rgba(3,105,161,0.15); }
.mtc-mode-badge:hover { border-color: rgba(3,105,161,0.4); background-color: rgba(3,105,161,0.05); }

/* --- Table Enhancements --- */
.mtc-sort-header { transition: background-color 0.15s ease; border-bottom: 2px solid rgba(3,105,161,0.15); }
.mtc-sort-header:hover { background-color: rgba(3,105,161,0.06); }
.mtc-table-row { transition: all 0.15s ease; }
.mtc-table-row:nth-child(even) { background-color: rgba(241,245,249,0.4); }
.mtc-table-row:nth-child(even):hover { background-color: rgba(3,105,161,0.04); }
.mtc-table-row:nth-child(odd):hover { background-color: rgba(3,105,161,0.04); }
.mtc-table-row:hover td:first-child { border-left: 3px solid #0369a1; padding-left: calc(0.75rem - 3px); }
.mtc-tbody { counter-reset: mtc-row; }
.mtc-tbody .mtc-table-row::before { counter-increment: mtc-row; }

/* --- Heat/Utilization Bars --- */
.mtc-heat-bar { border-radius: 6px; box-shadow: inset 0 1px 2px rgba(0,0,0,0.06); }
.mtc-util-fill { box-shadow: 0 0 6px rgba(3,105,161,0.2); transition: width 0.8s ease-out, box-shadow 0.3s ease; }
.mtc-util-fill:hover { box-shadow: 0 0 12px rgba(3,105,161,0.4); }

/* --- Transit Progress Bar --- */
.mtc-transit-bar { position: relative; }
.mtc-transit-bar::after { content: ''; position: absolute; top: 50%; left: 0; right: 0; height: 1px; background: repeating-linear-gradient(90deg, transparent, transparent 4px, rgba(3,105,161,0.15) 4px, rgba(3,105,161,0.15) 8px); transform: translateY(-50%); pointer-events: none; }

/* --- Value Tiles --- */
.mtc-value-tile { border: 1px solid rgba(3,105,161,0.08); border-radius: 8px; transition: all 0.2s ease; }
.mtc-value-tile:hover { border-color: rgba(3,105,161,0.2); box-shadow: 0 2px 8px rgba(3,105,161,0.06); }

/* --- Score Rings (SVG) --- */
.mtc-score-ring { filter: drop-shadow(0 1px 2px rgba(0,0,0,0.08)); transition: transform 0.3s ease; }
.mtc-score-ring:hover { transform: scale(1.05); }

/* --- Carbon Gauge --- */
.mtc-gauge { filter: drop-shadow(0 1px 3px rgba(0,0,0,0.06)); transition: transform 0.3s ease; }
.mtc-gauge:hover { transform: scale(1.08); }

/* --- Drawer Header Gradient --- */
.mtc-drawer-header { box-shadow: 0 4px 12px rgba(3,105,161,0.3); border-bottom: 2px solid rgba(255,255,255,0.1); }

/* --- Action Buttons --- */
.mtc-action-btn { transition: all 0.2s ease; }
.mtc-action-btn:hover { transform: translateY(-1px); box-shadow: 0 2px 8px rgba(3,105,161,0.15); }
.mtc-action-btn:active { transform: translateY(0); }

/* --- Shimmer loading effect on KPI grid --- */
.mtc-kpi-grid { position: relative; }
.mtc-kpi-grid::after { content: ''; position: absolute; top: 0; left: -100%; width: 50%; height: 100%; background: linear-gradient(90deg, transparent, rgba(3,105,161,0.03), transparent); animation: mtc-shimmer 8s infinite linear; pointer-events: none; z-index: 0; }
@keyframes mtc-shimmer { 0% { left: -100%; } 100% { left: 200%; } }

/* --- Risk Critical pulse --- */
.mtc-risk-critical { animation: mtc-risk-pulse 2s ease-in-out infinite; }
@keyframes mtc-risk-pulse {
  0%, 100% { box-shadow: 0 0 4px rgba(220,38,38,0.3); }
  50% { box-shadow: 0 0 14px rgba(220,38,38,0.6); transform: scale(1.05); }
}

/* --- Pulsing dot for active incidents --- */
.mtc-table-row:has(.mtc-risk-critical) { animation: mtc-row-pulse 3s ease-in-out infinite; }
@keyframes mtc-row-pulse {
  0%, 100% { background-color: transparent; }
  50% { background-color: rgba(220,38,38,0.03); }
}

/* --- Tab-specific row striping for different tabs --- */
.mtc-tab-0-row:nth-child(4n+1) { border-left: 3px solid #0369a1; }
.mtc-tab-1-row:nth-child(3n+1) { border-left: 3px solid #0d9488; }
.mtc-tab-2-row:nth-child(5n+1) { border-left: 3px solid #d97706; }
.mtc-tab-3-row:nth-child(2n+1) { border-left: 3px solid #059669; }
.mtc-tab-4-row:nth-child(7n+1) { border-left: 3px solid #dc2626; }

/* --- Hover card lift for KPI --- */
@keyframes mtc-kpi-entrance {
  from { opacity: 0; transform: translateY(8px); }
