/* --- KPI Cards: Multi-tone left border with gradient top stripe --- */
.tps-kpi-card { border-left: 4px solid transparent; border-radius: 8px; overflow: hidden; transition: all 0.25s ease; position: relative; }
.tps-kpi-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: linear-gradient(90deg, #4338ca, #0891b2, #d97706); opacity: 0; transition: opacity 0.3s ease; }
.tps-kpi-card:nth-child(1) { border-left-color: #4338ca; }
