/* ============================================================================
 * R255: Search Toolbar, Filter Chips, Enhanced Interactions, Animations
 * 80+ new CSS utility classes
 * ============================================================================ */

/* ── Search Toolbar ── */
.search-toolbar {
  background: oklch(1 0 0 / 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: all 0.2s ease;
}
.search-toolbar:hover {
  border-color: oklch(0 0 0 / 0.12);
}
:is(.dark) .search-toolbar {
  background: oklch(0.15 0 0 / 0.6);
  border-color: oklch(0 0 0 / 0.2);
}

.search-toolbar-row {
  gap: 8px;
  align-items: center;
}

/* ── Search Input ── */
.search-input-wrapper {
  position: relative;
  flex: 1;
  min-width: 200px;
  max-width: 420px;
}
.search-input-icon {
  transition: color 0.2s ease;
}
.search-input-wrapper:focus-within .search-input-icon {
  color: oklch(0.55 0.2 250);
}
.search-input {
  transition: all 0.2s ease;
  border: 1px solid oklch(0 0 0 / 0.08);
}
.search-input:focus {
  border-color: oklch(0.55 0.2 250);
  box-shadow: 0 0 0 3px oklch(0.55 0.2 250 / 0.1);
}
.search-clear-btn {
  opacity: 0;
  transition: all 0.15s ease;
}
.search-input:not(:placeholder-shown) ~ .search-clear-btn,
.search-input-wrapper:focus-within .search-clear-btn {
  opacity: 1;
}
.search-clear-btn:hover {
  background: oklch(0 0 0 / 0.08);
}

/* ── Filter Toggle Button ── */
.search-filter-toggle {
  transition: all 0.2s ease;
}
.search-filter-toggle:hover {
  transform: translateY(-1px);
}
.search-filter-toggle:active {
  transform: translateY(0);
}
.filter-count-badge {
  font-variant-numeric: tabular-nums;
  animation: badge-pop 0.2s ease;
}
@keyframes badge-pop {
  0% { transform: scale(0); }
  60% { transform: scale(1.2); }
  100% { transform: scale(1); }
}

/* ── Sort Button ── */
.search-sort-btn {
  transition: all 0.2s ease;
}
.search-sort-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 2px 4px oklch(0 0 0 / 0.06);
}
.search-sort-btn:active {
  transform: translateY(0);
}

/* ── Refresh Button ── */
.search-refresh-btn {
  transition: all 0.2s ease;
}
.search-refresh-btn:hover svg {
  color: oklch(0.55 0.2 250);
}

/* ── Item Count ── */
.search-count-number {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
  letter-spacing: -0.02em;
}
.search-count-label {
  color: oklch(0.5 0 0 / 0.6);
}
.search-count-total {
  color: oklch(0.5 0 0 / 0.4);
}
.search-item-count {
  white-space: nowrap;
}

/* ── Active Filter Chips ── */
.search-active-filters {
  padding-top: 8px;
  border-top: 1px solid oklch(0 0 0 / 0.04);
  animation: slide-down-fade 0.2s ease;
}
@keyframes slide-down-fade {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}
.filter-chip-active {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 9999px;
  font-size: 11px;
  font-weight: 500;
  background: oklch(0.55 0.2 250 / 0.08);
  color: oklch(0.55 0.2 250);
  border: 1px solid oklch(0.55 0.2 250 / 0.15);
  transition: all 0.15s ease;
  animation: chip-appear 0.15s ease;
}
.filter-chip-active:hover {
  background: oklch(0.55 0.2 250 / 0.15);
  border-color: oklch(0.55 0.2 250 / 0.25);
  transform: scale(1.02);
}
.filter-chip-active .filter-chip-label {
  max-width: 120px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
@keyframes chip-appear {
  from { opacity: 0; transform: scale(0.8); }
  to { opacity: 1; transform: scale(1); }
}
.filter-clear-all {
  font-size: 11px;
  text-decoration: underline;
  text-underline-offset: 2px;
  transition: all 0.15s ease;
}
.filter-clear-all:hover {
  text-decoration-thickness: 2px;
}

/* ── Filter Panel (expanded) ── */
.search-filter-panel {
  animation: expand-down 0.25s ease;
  overflow: hidden;
}
@keyframes expand-down {
  from { opacity: 0; max-height: 0; }
  to { opacity: 1; max-height: 400px; }
}
.filter-group {
  min-width: 0;
}
.filter-group-label {
  display: block;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: oklch(0.5 0 0 / 0.5);
  margin-bottom: 6px;
}
.filter-group-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.filter-chip {
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}
.filter-chip:hover {
  transform: translateY(-1px);
  box-shadow: 0 1px 3px oklch(0 0 0 / 0.08);
}
.filter-chip:active {
  transform: translateY(0);
}
.filter-chip-selected {
  box-shadow: 0 0 0 2px oklch(0.55 0.2 250 / 0.3);
}

/* ── Animated Expand Down (utility) ── */
.animate-expand-down {
  animation: expand-down 0.25s ease;
  overflow: hidden;
}

/* ── Animated Pulse Subtle ── */
.animate-pulse-subtle {
  animation: pulse-subtle 2s ease-in-out infinite;
}
@keyframes pulse-subtle {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

/* ── Enhanced Focus Ring Glow ── */
.focus-ring-glow:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px oklch(0.55 0.2 250 / 0.3), 0 0 8px oklch(0.55 0.2 250 / 0.15);
  border-color: oklch(0.55 0.2 250 / 0.5);
}

/* ── Glass Subtle ── */
.glass-subtle {
  background: oklch(1 0 0 / 0.4);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid oklch(0 0 0 / 0.06);
}
:is(.dark) .glass-subtle {
  background: oklch(0.15 0 0 / 0.4);
  border-color: oklch(0 0 0 / 0.15);
}

/* ── Glass Elevated ── */
.glass-elevated {
  background: oklch(1 0 0 / 0.7);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid oklch(0 0 0 / 0.08);
  box-shadow: 0 4px 12px oklch(0 0 0 / 0.06), 0 1px 3px oklch(0 0 0 / 0.04);
}
:is(.dark) .glass-elevated {
  background: oklch(0.18 0 0 / 0.7);
  border-color: oklch(0 0 0 / 0.2);
  box-shadow: 0 4px 12px oklch(0 0 0 / 0.2);
}

/* ── Stat Card Glow ── */
.stat-card-glow {
  position: relative;
  overflow: hidden;
}
.stat-card-glow::before {
  content: '';
  position: absolute;
  top: -2px;
  left: -2px;
  right: -2px;
  bottom: -2px;
  border-radius: inherit;
  background: linear-gradient(135deg, oklch(0.55 0.2 250 / 0.08), transparent 60%);
  z-index: -1;
  opacity: 0;
  transition: opacity 0.3s ease;
}
.stat-card-glow:hover::before {
  opacity: 1;
}

/* ── Badge Interactive ── */
.badge-interactive {
  cursor: pointer;
  transition: all 0.15s ease;
}
.badge-interactive:hover {
  transform: scale(1.05);
  filter: brightness(1.1);
  box-shadow: 0 2px 6px oklch(0 0 0 / 0.1);
}
.badge-interactive:active {
  transform: scale(0.98);
}

/* ── Chip Group (R255 enhanced) ── */
.chip-group {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.chip-group .chip,
.chip-group .filter-chip,
.chip-group .badge-interactive {
  transition: all 0.15s ease;
}
.chip-group .chip:hover,
.chip-group .filter-chip:hover {
  transform: translateY(-1px);
  box-shadow: 0 2px 4px oklch(0 0 0 / 0.06);
}

/* ── Progress Bar Animated (R255 enhanced) ── */
.progress-bar-animated {
  position: relative;
  overflow: hidden;
}
.progress-bar-animated::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, oklch(1 0 0 / 0.3), transparent);
  animation: progress-shimmer 2s ease-in-out infinite;
}
:is(.dark) .progress-bar-animated::after {
  background: linear-gradient(90deg, transparent, oklch(1 0 0 / 0.15), transparent);
}
@keyframes progress-shimmer {
  0% { left: -100%; }
  100% { left: 100%; }
}

/* ── Stat Value Animated ── */
.stat-value-animated {
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.stat-value-animated:hover {
  transform: scale(1.05);
}

/* ── Stat Change Arrow ── */
.stat-change-arrow {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 11px;
  font-weight: 600;
}
.stat-change-arrow-up {
  color: oklch(0.65 0.2 145);
}
.stat-change-arrow-down {
  color: oklch(0.65 0.2 25);
}

/* ── Scrollable Container ── */
.scrollable-container {
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: oklch(0 0 0 / 0.15) transparent;
}
.scrollable-container::-webkit-scrollbar {
  width: 6px;
}
.scrollable-container::-webkit-scrollbar-track {
  background: transparent;
}
.scrollable-container::-webkit-scrollbar-thumb {
  background: oklch(0 0 0 / 0.15);
  border-radius: 3px;
}
.scrollable-container::-webkit-scrollbar-thumb:hover {
  background: oklch(0 0 0 / 0.25);
}
:is(.dark) .scrollable-container {
  scrollbar-color: oklch(0 0 0 / 0.3) transparent;
}

/* ── Hover Reveal ── */
.hover-reveal > .hover-reveal-child {
  opacity: 0;
  transition: all 0.2s ease;
  pointer-events: none;
}
.hover-reveal:hover > .hover-reveal-child {
  opacity: 1;
  pointer-events: auto;
}
.hover-reveal-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  background: oklch(0.55 0.2 250 / 0.08);
  transition: all 0.15s ease;
}
.hover-reveal:hover .hover-reveal-icon {
  background: oklch(0.55 0.2 250 / 0.15);
}

/* ── Breadcrumb Glass (R255 enhanced) ── */
.breadcrumb-glass {
  background: oklch(1 0 0 / 0.5);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid oklch(0 0 0 / 0.06);
  border-radius: 8px;
  padding: 4px 12px;
}
:is(.dark) .breadcrumb-glass {
  background: oklch(0.15 0 0 / 0.5);
  border-color: oklch(0 0 0 / 0.15);
}
.breadcrumb-item-hover {
  transition: all 0.15s ease;
}
.breadcrumb-item-hover:hover {
  color: oklch(0.55 0.2 250);
}

/* ── Table Row Hover Highlight ── */
.table-hover-highlight tbody tr {
  transition: background-color 0.15s ease;
}
.table-hover-highlight tbody tr:hover {
  background-color: oklch(0.55 0.2 250 / 0.04);
}
:is(.dark) .table-hover-highlight tbody tr:hover {
  background-color: oklch(0.55 0.2 250 / 0.08);
}

/* ── Table Cell Truncate ── */
.table-cell-truncate {
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Table Cell Number ── */
.table-cell-number {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
  text-align: right;
}

/* ── Table Header Gradient ── */
.table-header-gradient thead {
  background: linear-gradient(180deg, oklch(0.97 0 0 / 1), oklch(0.95 0 0 / 1));
}
:is(.dark) .table-header-gradient thead {
  background: linear-gradient(180deg, oklch(0.18 0 0 / 1), oklch(0.16 0 0 / 1));
}

/* ── Table Footer ── */
.table-footer tfoot td {
  border-top: 2px solid oklch(0 0 0 / 0.1);
  font-weight: 600;
  background: oklch(0.97 0 0 / 0.5);
}
:is(.dark) .table-footer tfoot td {
  border-top-color: oklch(0 0 0 / 0.2);
  background: oklch(0.15 0 0 / 0.5);
}

/* ── Card Shine Effect ── */
.card-shine {
  position: relative;
  overflow: hidden;
}
.card-shine::after {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: linear-gradient(
    45deg,
    transparent 40%,
    oklch(1 0 0 / 0.08) 45%,
    oklch(1 0 0 / 0.12) 50%,
    oklch(1 0 0 / 0.08) 55%,
    transparent 60%
  );
  transform: translateX(-100%) rotate(0deg);
  transition: none;
}
.card-shine:hover::after {
  animation: shine-sweep 0.6s ease forwards;
}
@keyframes shine-sweep {
  from { transform: translateX(-100%) rotate(0deg); }
  to { transform: translateX(100%) rotate(0deg); }
}
:is(.dark) .card-shine::after {
  background: linear-gradient(
    45deg,
    transparent 40%,
    oklch(1 0 0 / 0.03) 45%,
    oklch(1 0 0 / 0.06) 50%,
    oklch(1 0 0 / 0.03) 55%,
    transparent 60%
  );
}

/* ── Card Gradient Overlay ── */
.card-gradient-overlay::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, oklch(0.55 0.2 250 / 0.03), transparent 50%);
  pointer-events: none;
  z-index: 0;
}
.card-gradient-overlay > * {
  position: relative;
  z-index: 1;
}

/* ── Button Shine ── */
.btn-shine {
  position: relative;
  overflow: hidden;
}
.btn-shine::after {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: linear-gradient(
    45deg,
    transparent 40%,
    oklch(1 0 0 / 0.15) 45%,
    oklch(1 0 0 / 0.2) 50%,
    oklch(1 0 0 / 0.15) 55%,
    transparent 60%
  );
  transform: translateX(-100%);
}
.btn-shine:hover::after {
  animation: shine-sweep 0.5s ease forwards;
}

/* ── Button Outline Animate ── */
.btn-outline-animate {
  position: relative;
  overflow: hidden;
}
.btn-outline-animate::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, oklch(0.55 0.2 250 / 0.05), transparent);
  opacity: 0;
  transition: opacity 0.2s ease;
}
.btn-outline-animate:hover::before {
  opacity: 1;
}

/* ── Input Focus Ring ── */
.input-focus-ring {
  transition: all 0.2s ease;
}
.input-focus-ring:focus {
  outline: none;
  border-color: oklch(0.55 0.2 250 / 0.5);
  box-shadow: 0 0 0 3px oklch(0.55 0.2 250 / 0.1), 0 0 8px oklch(0.55 0.2 250 / 0.05);
}

/* ── Input Hover Border ── */
.input-hover-border {
  transition: border-color 0.15s ease;
}
.input-hover-border:hover {
  border-color: oklch(0 0 0 / 0.15);
}
:is(.dark) .input-hover-border:hover {
  border-color: oklch(0 0 0 / 0.3);
}

/* ── Input Group ── */
.input-group {
  display: flex;
  align-items: center;
  border: 1px solid oklch(0 0 0 / 0.08);
  border-radius: 8px;
  overflow: hidden;
  transition: all 0.15s ease;
}
.input-group:focus-within {
  border-color: oklch(0.55 0.2 250 / 0.5);
  box-shadow: 0 0 0 3px oklch(0.55 0.2 250 / 0.08);
}
.input-group .input-prefix {
  padding: 0 10px;
