}
.input-group .input-suffix {
  padding: 0 10px;
  color: oklch(0.5 0 0 / 0.5);
  font-size: 13px;
  border-left: 1px solid oklch(0 0 0 / 0.06);
}

/* ── Badge Ring ── */
.badge-ring {
  position: relative;
}
.badge-ring::after {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  border: 1px solid currentColor;
  opacity: 0;
  transition: opacity 0.15s ease;
}
.badge-ring:hover::after {
  opacity: 0.2;
}

/* ── Badge Glow Variants ── */
.badge-glow-success {
  box-shadow: 0 0 8px oklch(0.65 0.2 145 / 0.3);
}
.badge-glow-warning {
  box-shadow: 0 0 8px oklch(0.8 0.18 85 / 0.3);
}
.badge-glow-danger {
  box-shadow: 0 0 8px oklch(0.65 0.22 25 / 0.3);
}

/* ── Badge Pulse ── */
.badge-pulse {
  animation: badge-pulse-anim 2s ease-in-out infinite;
}
@keyframes badge-pulse-anim {
  0%, 100% { box-shadow: 0 0 0 0 oklch(0.55 0.2 250 / 0.3); }
  50% { box-shadow: 0 0 0 4px oklch(0.55 0.2 250 / 0); }
