/* ── Dialog Polished ── */
.dialog-content-polished {
  border-radius: 12px;
  border: 1px solid oklch(0 0 0 / 0.08);
  box-shadow: 0 8px 32px oklch(0 0 0 / 0.12), 0 2px 8px oklch(0 0 0 / 0.06);
  animation: dialog-enter-polished 0.25s ease;
}
:is(.dark) .dialog-content-polished {
  border-color: oklch(0 0 0 / 0.2);
  box-shadow: 0 8px 32px oklch(0 0 0 / 0.3);
