}

/* ── Nav Item Indicator ── */
.nav-item-indicator {
  position: relative;
}
.nav-item-indicator::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 0;
  border-radius: 0 2px 2px 0;
  background: oklch(0.55 0.2 250);
  transition: height 0.2s ease;
}
.nav-item-indicator.active::before {
  height: 60%;
}

/* ── Tooltip Wrapper ── */
.tooltip-wrapper {
  position: relative;
  display: inline-flex;
}
.tooltip-wrapper .tooltip-content {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%) scale(0.95);
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 11px;
  white-space: nowrap;
  background: oklch(0.15 0 0 / 0.9);
  color: oklch(0.95 0 0);
  box-shadow: 0 4px 12px oklch(0 0 0 / 0.15);
  opacity: 0;
  pointer-events: none;
  transition: all 0.15s ease;
  z-index: 50;
}
.tooltip-wrapper:hover .tooltip-content {
  opacity: 1;
  transform: translateX(-50%) scale(1);
}

/* ── Scrollbar Utilities ── */
.scrollbar-thin {
  scrollbar-width: thin;
  scrollbar-color: oklch(0 0 0 / 0.15) transparent;
}
.scrollbar-thin::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.scrollbar-thin::-webkit-scrollbar-thumb {
  background: oklch(0 0 0 / 0.15);
  border-radius: 3px;
}
.scrollbar-none {
  scrollbar-width: none;
}
.scrollbar-none::-webkit-scrollbar {
  display: none;
}
.scrollbar-fade {
  mask-image: linear-gradient(to bottom, transparent, black 8px, black calc(100% - 8px), transparent);
  -webkit-mask-image: linear-gradient(to bottom, transparent, black 8px, black calc(100% - 8px), transparent);
}

