/* ==================== Air Cargo (acr-*) ==================== */
.acr-root{display:flex;flex-direction:column;gap:12px}
.acr-header{display:flex;align-items:center;justify-content:space-between;padding:10px 14px;background:linear-gradient(135deg,rgba(59,130,246,0.06),rgba(99,102,241,0.04));border-radius:10px;border:1px solid rgba(59,130,246,0.1)}
.acr-header-left{display:flex;align-items:center;gap:10px}
.acr-icon-wrap{width:36px;height:36px;border-radius:8px;background:rgba(59,130,246,0.1);display:flex;align-items:center;justify-content:center}
.acr-title{font-size:15px;font-weight:600;color:#1e293b}
.acr-subtitle{font-size:11px;color:#64748b;margin-top:1px}
.acr-live-count{font-size:11px;font-family:ui-monospace,monospace;color:#64748b;background:rgba(59,130,246,0.08);padding:2px 8px;border-radius:6px}
.acr-stats-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}
.acr-stat-card{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:8px;background:#fff;border:1px solid #e2e8f0}
.acr-stat-icon{width:28px;height:28px;border-radius:6px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.acr-stat-info{display:flex;flex-direction:column}
.acr-stat-value{font-size:15px;font-weight:700;font-family:ui-monospace,monospace}
.acr-stat-label{font-size:9px;color:#64748b;text-transform:uppercase;letter-spacing:0.5px}
.acr-controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.acr-secondary-filters{display:flex;align-items:center;flex-wrap:wrap;gap:6px;padding:0 2px}
.acr-filter-chip{display:flex;align-items:center;gap:4px;padding:4px 10px;border-radius:16px;font-size:11px;font-weight:500;border:1px solid #e2e8f0;background:#fff;cursor:pointer;transition:all 0.15s}
.acr-filter-chip:hover{border-color:rgba(59,130,246,0.3);background:rgba(59,130,246,0.04)}
.acr-filter-active{background:rgba(59,130,246,0.1);border-color:rgba(59,130,246,0.3);color:#2563eb}
.acr-type-chip{display:flex;align-items:center;gap:4px;padding:3px 10px;border-radius:12px;font-size:11px;border:1px solid #e2e8f0;background:#fff;cursor:pointer;transition:all 0.15s}
